PROOF indtype cm_value_ty = new_datatype_definition(
    "cm_value = CMIntV int | CMCharV int | CMNullV"
    " | CMPtrV int int int int cm_type");

PROOF indtype cm_function_d_ty = new_datatype_definition(
    "cm_function_d = CMFunctionD cm_type (cm_slot_d)list"
    " (cm_slot_d)list cm_stmt");

PROOF indtype cm_program_ty = new_datatype_definition(
    "cm_program = CMProgram (cm_struct_d)list (cm_global_d)list"
    " (cm_string_d)list (cm_function_d)list int");

PROOF thm cm_ltemps_def = new_fun_definition(
    `cm_ltemps (expr:cm_expr) : int =
       cm_tleft (cm_expr_tpair expr)`);

PROOF thm cm_rtemps_def = new_fun_definition(
    `cm_rtemps (expr:cm_expr) : int =
       cm_tright (cm_expr_tpair expr)`);

PROOF thm cm_temp_slots_def = new_fun_definition(
    `cm_temp_slots (f:cm_function_d) : int =
       cm_stemps (cm_function_body f)`);

PROOF thm cm_type_encode_def = new_fun_definition(
    `cm_type_encode (ty:cm_type) : int =
       1024i * cm_type_depth ty + cm_type_base_code ty`);

PROOF thm cm_integer_type_def = new_fun_definition(
    `cm_integer_type (ty:cm_type) : bool =
       (ty == CMIntTy || ty == CMCharTy)`);

PROOF thm cm_scalar_expr_type_def = new_fun_definition(
    `cm_scalar_expr_type (ty:cm_type) : bool =
       (cm_integer_type ty || cm_is_pointer ty)`);

PROOF thm cm_zero_literal_def = new_fun_definition(
    `cm_zero_literal (expr:cm_expr) : bool =
       (expr == CMConstE 0i CMIntTy)`);

PROOF thm cm_store_width_def = new_fun_definition(
    `cm_store_width (ty:cm_type) : int =
       (if ty == CMCharTy then 1i else 8i)`);

PROOF thm cm_string_generation_def = new_fun_definition(
    `cm_string_generation (p:cm_program) (index:int) : int =
       1i + ilength (cm_program_globals p) + index`);

PROOF thm cm_initial_mem_def = new_fun_definition(
    `cm_initial_mem (p:cm_program) : int->int =
       cm_write_bytes tower_zero_mem 8i (cm_static_data_bytes p)`);

PROOF thm cm_expr_rep_def = new_fun_definition(
    `cm_expr_rep (p:int) (e:cm_expr) : hprop =
       cm_expr_node p e (cm_expr_payload e)`);

PROOF thm cm_arg_list_rep_def = new_fun_definition(
    `cm_arg_list_rep (p:int) (args:(cm_expr)list) : hprop =
       cm_arg_tree args p`);

PROOF thm cm_stmt_rep_def = new_fun_definition(
    `cm_stmt_rep (p:int) (s:cm_stmt) : hprop =
       cm_stmt_node p s (cm_stmt_payload s)`);

PROOF thm cm_rep_string_length_def = new_fun_definition(
    `cm_rep_string_length (string:cm_string_d) : int =
       ilength (cm_string_bytes string)`);

PROOF thm cm_rep_string_size_def = new_fun_definition(
    `cm_rep_string_size (string:cm_string_d) : int =
       cm_rep_string_length string + 1i`);

PROOF thm cm_rep_is_pointer_code_def = new_fun_definition(
    `cm_rep_is_pointer_code (code:int) : int =
       (if 1024i <= code then 1i else 0i)`);

PROOF thm cm_rep_nonzero_def = new_fun_definition(
    `cm_rep_nonzero (n:int) : int =
       (if n == 0i then 0i else 1i)`);

PROOF thm cm_rep_program_valid_def = new_fun_definition(
    `cm_rep_program_valid (program:cm_program) : int =
       (if cm_wf_program program then 1i else 0i)`);

PROOF thm cm_char_normalize_count_def = new_fun_definition(
    `cm_char_normalize_count (ty:cm_type) : int =
       (if ty == CMCharTy then 6i else 0i)`);

PROOF thm cm_function_prologue_count_def = new_fun_definition(
    `cm_function_prologue_count (f:cm_function_d) : int =
       14i + cm_param_stores_count (cm_function_params f)`);

PROOF thm cm_model_code_length_def = new_fun_definition(
    `cm_model_code_length (p:cm_program) : int =
       11i + cm_functions_code_size p (cm_program_functions p) 0i`);

PROOF thm cm_max_function_arity_def = new_fun_definition(
    `cm_max_function_arity (p:cm_program) : int =
       cm_max_function_arity_from (cm_program_functions p)`);

PROOF thm cm_stack_bound_model_def = new_fun_definition(
    `cm_stack_bound_model (p:cm_program) : int =
       3i + cm_max_function_arity p`);

PROOF thm cm_const_immediate_def = new_fun_definition(
    `cm_const_immediate (ty:cm_type) (n:int) : int =
       (if ty == CMCharTy then tower_u8 n else n)`);

PROOF thm cm_char_normalize_code_def = new_fun_definition(
    `cm_char_normalize_code (ty:cm_type) : (tvm_inst)list =
       (if ty == CMCharTy
        then [TVMInst TVMPushOp 256i; TVMInst TVMModOp 0i;
              TVMInst TVMPushOp 256i; TVMInst TVMAddOp 0i;
              TVMInst TVMPushOp 256i; TVMInst TVMModOp 0i]
        else [])`);

PROOF thm cm_load_code_def = new_fun_definition(
    `cm_load_code (ty:cm_type) : (tvm_inst)list =
       [TVMInst (if ty == CMCharTy then TVMLoadBOp else TVMLoadOp) 0i]`);

PROOF thm cm_store_code_def = new_fun_definition(
    `cm_store_code (ty:cm_type) : (tvm_inst)list =
       [TVMInst (if ty == CMCharTy then TVMStoreBOp else TVMStoreOp) 0i]`);

PROOF thm cm_emit_prologue_def = new_fun_definition(
    `cm_emit_prologue (p:cm_program) (fid:int) : (tvm_inst)list =
       [TVMInst TVMPushOp 8i; TVMInst TVMLoadOp 0i;
        TVMInst TVMDupOp 0i;
        TVMInst TVMPushOp
          (cm_frame_size (cm_program_structs p)
            (inth fid (cm_program_functions p)));
        TVMInst TVMSubOp 0i; TVMInst TVMStoreOp 0i;
        TVMInst TVMPushOp 8i; TVMInst TVMLoadOp 0i;
        TVMInst TVMPushOp
          (cm_frame_size (cm_program_structs p)
            (inth fid (cm_program_functions p)));
        TVMInst TVMSubOp 0i; TVMInst TVMDupOp 0i;
        TVMInst TVMPushOp 8i; TVMInst TVMStoreOp 0i;
        TVMInst TVMPopOp 0i] ++
       cm_emit_param_stores p fid 0i
         (cm_function_params
           (inth fid (cm_program_functions p)))`);

PROOF thm cm_emit_prelude_def = new_fun_definition(
    `cm_emit_prelude (p:cm_program) : (tvm_inst)list =
       [TVMInst TVMPushOp 1048576i;
        TVMInst TVMPushOp 8i; TVMInst TVMStoreOp 0i;
        TVMInst TVMCallOp (cm_function_pc p (cm_program_main p));
        TVMInst TVMPushOp 256i; TVMInst TVMModOp 0i;
        TVMInst TVMPushOp 256i; TVMInst TVMAddOp 0i;
        TVMInst TVMPushOp 256i; TVMInst TVMModOp 0i;
        TVMInst TVMHaltOp 0i]`);

PROOF thm cm_model_patches_def = new_fun_definition(
    `cm_model_patches (p:cm_program) : (tvm_patch)list =
       cm_bytes_patches (cm_model_data_bytes p) 8i`);

PROOF thm cm_compile_model_def = new_fun_definition(
    `cm_compile_model (p:cm_program) : tvm_object =
       TVMObject 0i (cm_model_code p) (cm_model_patches p)`);

PROOF thm cm_model_data_length_def = new_fun_definition(
    `cm_model_data_length (p:cm_program) : int =
       ilength (cm_model_data_bytes p)`);

PROOF thm cm_wf_program_def = new_fun_definition(
    `cm_wf_program (p:cm_program) : bool =
       cm_codegen_admissible p`);
